int numIslands(vector<vector<char>>& g) {
    int R = g.size(), C = g[0].size(), n = 0;
    for (int r = 0; r < R; r++) for (int c = 0; c < C; c++) if (g[r][c] == '1') {
        n++; vector<pair<int,int>> st{{r, c}}; g[r][c] = '0';
        while (!st.empty()) { auto [y, x] = st.back(); st.pop_back(); int d[5] = {1, 0, -1, 0, 1};
            for (int k = 0; k < 4; k++) { int yy = y + d[k], xx = x + d[k + 1]; if (yy >= 0 && yy < R && xx >= 0 && xx < C && g[yy][xx] == '1') { g[yy][xx] = '0'; st.push_back({yy, xx}); } } }
    }
    return n;
}
